import fs from 'fs/promises';
import path from 'path';
import { unstable_cache } from 'next/cache';

export type Post = {
  id: string;
  title: string;
  content: string;
  createdAt: string;
};

const DB_PATH = path.join(process.cwd(), 'posts.json');

// Helper to initialize DB if not exists
async function ensureDB() {
  try {
    await fs.access(DB_PATH);
  } catch {
    await fs.writeFile(DB_PATH, JSON.stringify([]));
  }
}

// Raw data access
async function readPostsRaw(): Promise<Post[]> {
  await ensureDB();
  const data = await fs.readFile(DB_PATH, 'utf-8');
  return JSON.parse(data);
}

// Cached data access
export const getPosts = unstable_cache(
  async () => {
    return readPostsRaw();
  },
  ['posts'], // keyParts
  { tags: ['posts'] } // options with tags
);

export async function addPost(post: Post) {
  const posts = await readPostsRaw();
  posts.push(post);
  await fs.writeFile(DB_PATH, JSON.stringify(posts, null, 2));
}

'use server';

import { addPost } from './lib/db';
import { revalidateTag } from 'next/cache';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title || !content) {
    throw new Error('Title and content are required');
  }

  const newPost = {
    id: Date.now().toString(),
    title,
    content,
    createdAt: new Date().toISOString(),
  };

  await addPost(newPost);

  // Invalidate the cache for the 'posts' tag
  // This ensures the next fetch for this tag will get fresh data
  revalidateTag('posts');
}

