import { getPosts } from './lib/db';
import { createPost } from './actions';

export const dynamic = 'force-dynamic';

export default async function Home() {
  const posts = await getPosts();

  return (
    <main style={{ padding: '2rem' }}>
      <h1>Posts</h1>

      <div style={{ marginBottom: '2rem', border: '1px solid #ccc', padding: '1rem' }}>
        <h2>Create New Post</h2>
        <form action={createPost}>
          <div style={{ marginBottom: '1rem' }}>
            <label style={{ display: 'block', marginBottom: '0.5rem' }}>Title</label>
            <input name="title" type="text" style={{ width: '100%', padding: '0.5rem' }} required />
          </div>
          <div style={{ marginBottom: '1rem' }}>
            <label style={{ display: 'block', marginBottom: '0.5rem' }}>Content</label>
            <textarea name="content" style={{ width: '100%', padding: '0.5rem', minHeight: '100px' }} required />
          </div>
          <button type="submit" style={{ padding: '0.5rem 1rem', background: '#0070f3', color: 'white', border: 'none', borderRadius: '4px' }}>
            Create Post
          </button>
        </form>
      </div>

      <div className="posts">
        {posts.length === 0 ? (
          <p>No posts yet.</p>
        ) : (
          posts.map((post) => (
            <article key={post.id} style={{ marginBottom: '1rem', borderBottom: '1px solid #eee', paddingBottom: '1rem' }}>
              <h3>{post.title}</h3>
              <p>{post.content}</p>
              <small style={{ color: '#666' }}>{new Date(post.createdAt).toLocaleString()}</small>
            </article>
          ))
        )}
      </div>
    </main>
  );
}

